insert into public.question_catalog(id,unit_code,question_order,question_text,choices,correct_index,explanation)
values
  ('q_8b452b2d86e0bc3822942602','經濟學十大原理',1,'下列對生產可能線（production possibility frontier）的敘述，何者錯誤？','["生產可能線內部的生產組合，是資源已做充分利用下的產出","生產可能線線上的生產組合，是技術已做最有效率利用下的產出","生產可能線線上的生產組合，是資源已做充分利用下的產出","生產可能線外部的生產組合，可能是技術未能達到的產出。"]'::jsonb,0,'題庫答案為 A。本題屬於「經濟學十大原理」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_0eb9ce50b13bcef3f211135c','經濟學十大原理',2,'飲料店評估是否延長營業一小時，最適合比較什麼？','["全天總收入與租金","新增一小時的邊際利益與邊際成本","昨天的平均收入","店長的沉沒成本"]'::jsonb,1,'理性決策者會在邊際上比較新增利益與新增成本。'),
  ('q_dc4b57efd845bcc9127e1ded','經濟學十大原理',3,'政府提高香菸稅後，部分消費者減少購買，最能說明哪項原理？','["人們會回應誘因","貿易使每個人變壞","市場永遠失靈","成本不影響選擇"]'::jsonb,0,'稅提高了購買成本，行為改變反映人們會回應誘因。'),
  ('q_94a61e700493013a5b6e3457','經濟學十大原理',4,'為了多念一小時經濟學而少休息一小時，最能呈現什麼？','["通貨膨脹","取捨","規模經濟","市場力量"]'::jsonb,1,'資源與時間有限，因此取得某物通常必須放棄另一物。'),
  ('q_942f14b8001eadb0cc0356e5','經濟學十大原理',5,'市場無法把污染成本反映在價格時，政府介入的主要理由是什麼？','["提高所有廠商利潤","改善市場失靈","取消所有誘因","保證每個人收入lasse相同"]'::jsonb,1,'污染是外部性，屬於市場失靈的一種。'),
  ('q_3542b708ce55e87873f3d002','機會成本',1,'「天下沒有白吃的午餐」意指：','["有得必有失","毋需計較得失","得失難以衡量","得失難以取捨。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_393dbffabd060d6ec03d569f','機會成本',2,'請根據以下資料寫出台灣之(直線型)生產可能線(production possibility curve - PPC)方程式內的係數：台灣全國共有200個勞工，其中每一單位青菜(V)需使用10個勞工、每一單位平板電腦(T)則需20個勞工。若QV、QT各代表青菜或電腦之產出量，其PPC即為(   QV)+(   QT)= 200；此時，台灣每生產1單位V的機會成本為(放棄)   (個T)、每生產1單位T的機會成本為   (個V)。以上四個空格的答案依序為：','["10, 20, 1/2, 2","20, 10, 2, 1/2","1, 2, 2, 1/2","2, 1, 1/2, 2。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_9d4498e04f0fdfa4f0f0b1b9','機會成本',3,'下列何者不是生產可能線整條移動的因素？','["機會成本遞減","經濟結構改變","整個社會體制改變","技術進步。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_b2a2c74158b354cc4b85433e','機會成本',4,'經濟學所稱的成本為','["機會成本","外顯成本","隱藏成本","邊際成本。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_a23c383a123d7492194c397e','機會成本',5,'一個大學生徹夜玩網路遊戲，下列何者不是他玩網路遊戲的機會成本？','["購買遊戲道具的支出","晚餐支出","隔天翹課","使用電腦上網的電費。"]'::jsonb,1,'題庫答案為 B。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_fc05688df96c42db4835bd17','機會成本',6,'小李畢業後有甲、乙、丙三個工作機會，甲工作月薪為X 元，乙工作月薪為Y 元，丙工作月薪為Z 元，且X>Y>Z。在其他條件相同下，小李選擇甲、乙、丙三個工作的機會成本依序為：','["Y、Z、X","Z、X、Y","Y、X、X","X、X、Y。"]'::jsonb,2,'題庫答案為 C。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_8de3e0f51e5580c12dd7a2a1','機會成本',7,'一個國家的生產可能曲線，可以用它來解釋下列何種觀念？','["企業與企業家之差異","創新與發明之差異","稀少性與機會成本之概念","一國消費財貨之數量。"]'::jsonb,2,'題庫答案為 C。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_ac5e8a5a5f34492c690b4dd9','機會成本',8,'假設某農家為了多生產 45 公斤稻米必須少生產 15 公斤蔬菜，則生產一公斤稻米的機會成本為：','["3 公斤稻米","3 公斤蔬菜","1/3 公斤蔬菜","1/3 公斤稻米。"]'::jsonb,2,'題庫答案為 C。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_453f43e45e32f612abbf4ae1','機會成本',9,'下列那一個觀念不能以生產可能線來說明的?','["機會成本","稀少性","均衡價格","經濟發展。"]'::jsonb,2,'題庫答案為 C。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_cc284ae664522ebb234c6688','機會成本',10,'假設有稻米與花卉二項商品，其生產可能線凸向外，則下列敘述何者正確?','["生產稻米與花卉的邊際機會成本都遞增","生產稻米與花卉的邊際機會成本都遞減","生產稻米的邊際機會成本遞增，生產花卉的邊際機會成本遞減","生產稻米的邊際機會成本遞減，生產花卉的邊際機會成本遞增。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_7dfaf1ca24eb9029228b3a70','機會成本',11,'下列何種情況發生「不會」使一個國家的生產可能曲線移動位置?','["邊際機會成本遞增","引進外籍勞工","技術水準進步","國內產業外移國外。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_50a8dc7ef6a456ab8280ffe1','機會成本',12,'一個能力差的人可以與一個能力強的人分工合作，而且兩人都可從中獲利，是因為：','["兩人對不同生產項目的機會成本不同","兩人對不同生產項目的生產力不同：","能力強的人具有同情心","能力差的人工作更勤奮。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_99ffcf2acc39255d6095fcd4','機會成本',13,'生產可能線上某一生產組合為10個梨子與7個蘋果，同一生產可能線上之另一生產組合為8個梨子與10個蘋果。則這兩個組合間，生產一個梨子的機會成本為何？','["7/10個蘋果","2/3個蘋果","10/8個蘋果","3/2個蘋果。"]'::jsonb,3,'題庫答案為 D。本題屬於「機會成本」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_b8d6534e2d97d1706326dc12','機會成本與比較利益',1,'亞當斯密A. Smith曾說過，社會的經濟活動在冥冥中受到一隻「看不見的手」的支配，這隻「看不見的手」是指','["市場價格機能","政府的經濟政策","國際貿易的活動","企業精神。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本與比較利益」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_9016026f1e66ace5a2e0ccce','機會成本與比較利益',2,'下列哪一個是「規範性」的?','["效率比公平重要","專業分工可以創造雙贏","有得必有失","opportunity cost決定比較利益。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本與比較利益」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_e3eb6fe7094c00625cb12846','機會成本與比較利益',3,'A國的果農每年可生產100斤梨子或200斤葡萄，B國的果農每年可生產80斤梨子或120斤葡萄。假設A、B兩國各有果農500人，下列敘述何者正確？','["兩國沒有交易利益","A國生產梨子的opportunity cost較B國高，故沒有絕對利益","B國生產梨子或葡萄都有絕對利益","B國生產葡萄的opportunity cost較A國高，故沒有比較利益。"]'::jsonb,3,'題庫答案為 D。本題屬於「機會成本與比較利益」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_dedf41fb04a979fd35b6c906','機會成本與比較利益',4,'小王一個小時可以做 80 個包子或 3 個蛋糕，小魏一個小時可以做 100 個包子或 6 個蛋糕。則小魏做那一項有「比較利益」?','["包子","蛋糕","兩者皆有","兩者皆無。"]'::jsonb,1,'題庫答案為 B。本題屬於「機會成本與比較利益」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_56b0233e7e0e04cf9f204e1b','機會成本與比較利益',5,'可以「合則兩利」的分工專業原則，是：','["龍配龍、鳳配鳳","具有絕對利益","資源較豐富","具有比較利益。"]'::jsonb,3,'題庫答案為 D。本題屬於「機會成本與比較利益」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_969b8565abcbdf82807ea8c5','機會成本與比較利益',6,'「天生我材必有用」與下列那個觀念最有關：','["比較利益","絕對利益","稀少性","選擇。"]'::jsonb,0,'題庫答案為 A。本題屬於「機會成本與比較利益」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_ad31fa75a7135e3f5b2bd41a','需求概念',1,'如果甲財貨的價格下降而使乙財貨的需要量減少，則稱甲、乙財貨為','["正常財貨","劣等財貨","替換財貨","互補財貨。"]'::jsonb,2,'題庫答案為 C。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_4f5b64a51c6ed9c624d058dc','需求概念',2,'假設張生與崔姐為檸檬市場中的惟二消費者，在1 個月中，若張生的需求關係為當檸檬價格為每斤50 元與100 元時，張生對檸檬需求量分別為15 個與10 個；而崔姐的需求關係為當檸檬價格為每斤50 元與100元時，崔姐對檸檬需求量分別為10 個與6 個；則下列何項會在檸檬的市場需求曲線上？','["市場需求量為41 個，市場價格為150 元","市場需求量為41 個，市場價格為100 元","市場需求量為16 個，市場價格為100 元","市場需求量為20 個，市場價格為50 元。"]'::jsonb,2,'題庫答案為 C。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_d91958d871f7a489d354cd75','需求概念',3,'若 X 的需求函數為 P ﹦10 ﹣Q ﹢0.5S ﹢0.2I，S 為 Y 之價格而 I 表示所得，則下列何者正確?','["X為劣等品且與Y為互補品","X為正常品且與Y為互補品","X為劣等品且與Y為替代品","X為正常品且與Y為替代品。"]'::jsonb,3,'題庫答案為 D。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_f427e968568215ce47a92b73','需求概念',4,'牛奶價格大漲民眾紛紛改喝豆漿，則下列敘述何者錯誤？','["牛奶和豆漿是替代品","黃豆價格可能上漲","牛奶的需求線左移","豆漿的需求線右移。"]'::jsonb,2,'題庫答案為 C。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_31b6606a70414b2a1ef460b2','需求概念',5,'某物品的合作性或補充性財貨價格上漲，會使得該物品如何？','["整條需求線左移","整條需求線右移","整條需求線不變","沿著需求線需求量減少。"]'::jsonb,0,'題庫答案為 A。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_824058b06c6b5cd41cbe28f9','需求概念',6,'列何者為違反需求法則的財貨?','["正常財","必需品","奢侈品","炫耀性財貨。"]'::jsonb,3,'題庫答案為 D。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_8c75d72204cb18836d6c3526','需求概念',7,'某財貨X的需求函數寫為QX=ePX+fI+gPY，I指所得或預算、PY為另一商品Y的單價，（e, f, g則為各變數的係數）；若X是季芬財(Giffen good)， 則     >0；若X為劣等財(inferior good)，則   <0；若X與Y之間為互補品(complements)，則g   0。以上三個空格的答案依序為：','["PX, I, =","e, f, <","f, e, >","e+f, f-e, =。"]'::jsonb,1,'題庫答案為 B。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_9b3823d5f10a862e37c75ca4','需求概念',8,'某財貨Y的需求函數寫為QY=400-3PY-4I+2PX；則Y   季芬財、Y   劣等財、Y與X之間為   。以上三個空格的答案依序為：','["是、是、互補品","不是、是、替代品","不是、不是、互補品","不是、不是、替代品。"]'::jsonb,1,'題庫答案為 B。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_990ff6c0f3218884cd6c5fca','需求概念',9,'以下對財貨X之需求線的敘述何者正確：','["需求法則指該線之斜率為正","X與另一財貨Y之間為互補品，則前者的需求線斜率必為負","由需求函數(如)QY=360-3PY+2PX，即可畫出X之需求線","其他條件不變下，季芬財指其價格與需求量成正向變動關係。"]'::jsonb,3,'題庫答案為 D。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_daeaa44a8f0b5ae809a0bc6c','需求概念',10,'柳丁與橘子為替代品，若因蟲害而使柳丁供給減少，則對橘子市場有何影響?','["價格上升，交易量減少","價格下降，交易量增加","價格下降，交易量減少","價格上升，交易量增加。"]'::jsonb,3,'題庫答案為 D。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_19ffa3c3474e1a4c245d6791','需求概念',11,'市場價格引導資源配置的作用，我們稱之為','["價格機能","理性選擇","市場均衡","需求法則。"]'::jsonb,0,'題庫答案為 A。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_7dfa298c3ae93bf4806fed12','需求概念',12,'下列對市場均衡之描述何者有誤？','["只要有供需，市場均衡必定存在","為需求曲線與供給曲線之交點","若無其他因素改變供需，市場將持續保持均衡","個人之行為無法影響市場均衡。"]'::jsonb,0,'題庫答案為 A。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_51fe1c92ca464e5684c74215','需求概念',13,'當空心菜價格一斤為10元時，市場需求量為100斤，價格上升為一斤30元時，需求量降為60斤，試求出需求之弧彈性','["0.2","1","0.5","以上皆非。"]'::jsonb,2,'題庫答案為 C。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_96b977b31ddfbd53dcab3252','需求概念',14,'下列敘述何者正確','["民生必需品較缺乏需求彈性","奢侈品較缺乏需求彈性","替代品多之物品較缺乏需求彈性","以上皆非。"]'::jsonb,0,'題庫答案為 A。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
  ('q_f24c60ba36d9f289433776f1','需求概念',15,'假設鋼鐵市場的需求曲線為 QD=10P ，且市場的供給曲線為QS=-5+2P，其中 P 為價格，QD 為市場需求量， QS 為市場供給量。若政府對鋼鐵市場設定價格下限（price floor）為每單位 4 元，市場的鋼鐵成交價格及成交數量分別為：','["4元及 6 單位","5元及 5 單位","6 元及 4 單位","7元及 3 單位。"]'::jsonb,1,'題庫答案為 B。本題屬於「需求概念」，請依核心定義與成立條件逐一排除其他選項。'),
